    return ds;
}

public boolean control_modified(FormControl _control)
{
    MethodName              callMethod = SysTest::hasMethod(_control,methodStr(FormCheckBoxControl, value)) ? methodStr(FormCheckBoxControl, value) : methodStr(FormControl, valueStr);
    ClassName				usedClass = controlName2ClassName.exists(_control.name()) ? controlName2ClassName.lookup(_control.name()) : currentClass;
    TFMGenericParms::CreateOrUpdateParameter(usedClass,_control.name(),ds.tableName + '/' + ds.ordertype, new SysDictClass(classIdGet(_control)).callObject(callMethod,_control));


    return true;
}

public boolean control_EnumModified(FormComboBoxControl _control)
{
    MethodName              callMethod = SysTest::hasMethod(_control,methodStr(FormCheckBoxControl, value)) ? methodStr(FormCheckBoxControl, value) : methodStr(FormControl, valueStr);
    str						value = new SysDictClass(classIdGet(_control)).callObject(callMethod,_control);
    ClassName				usedClass = controlName2ClassName.exists(_control.name()) ? controlName2ClassName.lookup(_control.name()) : currentClass;
    TFMGenericParms::CreateOrUpdateParameter(usedClass, _control.name(), ds.tableName + '/' + ds.ordertype, TFMDocCustomFunctionFlow::ConvertToType(value,Types::Enum,enumId2Name(_control.enumTypeValue())));

    return true;
}

protected anytype getValue(ClassName _domain, MethodName _key, Description255 _content = '')
{

    return TFMGenericParms::getValue(_domain,_key,ds.TableName +'/'+ ds.OrderType);
}

protected boolean valueExists(ClassName _domain, MethodName _key)
{
    return TFMGenericParms::Exists(_domain,_key,ds.TableName +'/'+ ds.OrderType);
}

    public FormControl type2FormControl(FormGroupControl _fgc, Types _baseType, ExtendedTypeId _edtId, MethodName _methodName, anytype _defaultValue = null, labelString _labelStringOverride = '', HelpTxt _helpTextOverride = '')
